/* R7 (H12): neither frame loads with the page. The active case mounts when
   #exempelcase comes within two viewports (IntersectionObserver, bottom
   margin 100 %, so no layout read per scroll frame); the other case mounts
   after it, when the browser is idle. A click on a case that has not
   mounted yet mounts it at once (activateCase). No refresh from here. */
var exempelcaseEl = document.getElementById('exempelcase');
function mountCase(C){
  var f = C && C.iframe;
  if (!f || f.getAttribute('src')) return;
  var src = f.getAttribute('data-lazy-src');
  if (!src) return;
  scaleShowcaseFrame();
  C.mountedAt = performance.now();
  f.setAttribute('src', src);
  f.removeAttribute('data-lazy-src');
}
function otherCase(key){ return key === 'calyx' ? CASES.horai : CASES.calyx; }
if ('IntersectionObserver' in window && exempelcaseEl){
  var mountIO = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting || e.boundingClientRect.top < 0){
        mountCase(CASES[activeCaseKey]);
        mountIO.disconnect();
      }
    });
  }, { rootMargin: '0px 0px 100% 0px' });
  mountIO.observe(exempelcaseEl);
} else {
  mountCase(CASES[activeCaseKey]);
}

/* R5 bugfix (kept): pinning an ancestor of a live iframe makes GSAP's own
   pin-spacer wrap (on creation) and unwrap/rewrap (on every later
   revert-and-remeasure inside ScrollTrigger.refresh()) move that
   ancestor in the DOM - and moving an iframe element's ancestor makes
   the browser reload it. Confirmed by instrumenting the calyx iframe's
   own 'load' event: it fired twice on a single page load, a frame apart,
   matching two refresh() passes. A one-shot {once:true} listener caught
   only the first reload and kept a stale, detached contentWindow after

