/* R7 (H12): neither frame loads with the page. The active case becomes due
   when #exempelcase comes within two viewports (IntersectionObserver, bottom
   margin 100 %, so no layout read per scroll frame). Loading a site costs
   ~0.5 s of main-thread script (Tailwind's in-browser compile, measured:
   tasks of 160 + 330 ms for Calyx, 560 ms for Hōrai), so a due frame is
   mounted at the reader's first scroll pause (Lenis at rest for 180 ms),
   and at the latest when #showcase is 0.6 viewport away; its fallback image
   covers until it has loaded. The other case mounts at the next pause
   after that, or on intent (pointer or focus on its button), or on click
   (activateCase). No refresh from here. */
var lastScrollAt = 0, pendingMounts = [], pausePoll = null;
lenis.on('scroll', function(){ lastScrollAt = performance.now(); });
function mountWhenPaused(C){
  if (!C || C.iframe.getAttribute('src') || pendingMounts.indexOf(C) > -1) return;
  pendingMounts.push(C);
  if (pausePoll) return;
  (function poll(){
    if (!lenis.isScrolling && performance.now() - lastScrollAt > 180){
      var next = pendingMounts.shift();
      if (next) mountCase(next);
      pausePoll = pendingMounts.length ? setTimeout(poll, 400) : null;
      return;
    }
    pausePoll = setTimeout(poll, 120);
  })();
}

